fn it_ssize_arg(v: &V) -> Result<i64, E> {
    let x = match v {
        V::Int(i) => *i,
        V::Bool(b) => *b as i64,
        V::Big(_) => return Err(exc("OverflowError", "Python int too large to convert to C ssize_t".into())),
